function profile(distance, vmax, a) {
  const d = Math.abs(distance);
  if (d < 1e-9) return { T: 0, d: 0, pos: () => 0, vel: () => 0 };
  const dAcc = (vmax * vmax) / a;
  let ta, tc, vp;
  if (d >= dAcc) {
    ta = vmax / a;
    tc = (d - dAcc) / vmax;
    vp = vmax;
  } else {
    vp = Math.sqrt(d * a);
    ta = vp / a;
    tc = 0;
  }
  const T = 2 * ta + tc;
  const sign = Math.sign(distance);
  const pos = (t) => {
    if (t <= 0) return 0;
    if (t >= T) return distance;
    let s;
    if (t < ta) s = 0.5 * a * t * t;
    else if (t < ta + tc) s = 0.5 * a * ta * ta + vp * (t - ta);
    else s = d - 0.5 * a * (T - t) * (T - t);
    return sign * s;
  };
  const vel = (t) => {
    if (t <= 0 || t >= T) return 0;
    let v;
    if (t < ta) v = a * t;
    else if (t < ta + tc) v = vp;
    else v = a * (T - t);
    return sign * v;
  };
  return { T, d, pos, vel };
}

